'use strict';

(function () {
    const hamburgerIcon = document.getElementById("hamburger");
    let isMenuOpen = true;

    function openMenu() {
        let sections = document.querySelectorAll("#home, #projects, #about, #contact");
        hamburgerIcon.classList.add("icon--hamburger--active");

        sections.forEach(section => {
            section.classList.add("nav__element");
            section.classList.add("nav__element--" + section.id);

            section.addEventListener("click", () => {
                closeMenu();
                location.href = "#" + section.id;
            });
        });

        isMenuOpen = false;
    }

    function closeMenu() {
        let sections = document.querySelectorAll("#home, #projects, #about, #contact");
        hamburgerIcon.classList.remove("icon--hamburger--active");
        document.getElementById("bg-video")?.play();

        sections.forEach(section => {
            section.classList.remove("nav__element");
            section.classList.remove("nav__element--" + section.id);
        });

        isMenuOpen = true;
    }

    if (window.IntersectionObserver) {
        const socialActions = document.querySelector(".social-actions");
        const contactSection = document.getElementById("get-in-touch");

        const contactObserver = new IntersectionObserver(entries => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    socialActions.classList.add("return");
                } else {
                    socialActions.classList.remove("return");
                }
            });
        });

        if (contactSection) {
            contactObserver.observe(contactSection);
        }

        const animateObserver = new IntersectionObserver(entries => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add(entry.target.getAttribute("data-animation"));
                    entry.target.classList.remove("animate");
                    animateObserver.unobserve(entry.target);
                }
            });
        });

        document.querySelectorAll(".animate").forEach(element => {
            animateObserver.observe(element);
        });

        const videoObserver = new IntersectionObserver(entries => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.play();
                    videoObserver.unobserve(entry.target);
                }
            });
        }, { threshold: 0.5 });

        document.querySelectorAll("video").forEach(video => {
            videoObserver.observe(video);
        });

    } else {
        console.log("IntersectionObserver not present");
    }

    hamburgerIcon?.addEventListener("click", () => {
        isMenuOpen ? openMenu() : closeMenu();
    });
})();

// Day / night switch
document.addEventListener("DOMContentLoaded", () => {
    const root = document.documentElement;
    const toggle = document.getElementById("theme-toggle");
    if (!toggle) return;

    const icon = toggle.querySelector("i");

    function apply(theme) {
        if (theme === "night") {
            root.setAttribute("data-theme", "night");
        } else {
            root.removeAttribute("data-theme");
        }
        const next = theme === "night" ? "day" : "night";
        toggle.setAttribute("aria-label", "Switch to " + next + " mode");
        toggle.setAttribute("title", "Switch to " + next + " mode");
        if (icon) icon.className = theme === "night" ? "fas fa-sun" : "fas fa-moon";
    }

    apply(root.getAttribute("data-theme") === "night" ? "night" : "day");

    toggle.addEventListener("click", () => {
        const next = root.getAttribute("data-theme") === "night" ? "day" : "night";
        apply(next);
        try { localStorage.setItem("theme", next); } catch (e) {}

        // replay the rise so the sun / moon comes up again on every switch
        const body = document.querySelector(".sun");
        if (body) {
            body.style.animation = "none";
            void body.offsetWidth;
            body.style.animation = "";
        }
    });
});

document.addEventListener("DOMContentLoaded", () => {
    const container = document.querySelector(".bubbles-container");
    if (!container) return;

    for (let i = 0; i < 20; i++) {
        const bubble = document.createElement("div");
        bubble.classList.add("bubble");
        bubble.style.left = `${Math.random() * 100}%`;
        bubble.style.animationDuration = `${Math.random() * 10 + 5}s`;
        container.appendChild(bubble);
    }
});

// Project category tabs functionality
document.addEventListener("DOMContentLoaded", () => {
    const categoryBtns = document.querySelectorAll(".category-btn")
    const projectContainers = document.querySelectorAll(".project-category-container")

    categoryBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        // Remove active class from all buttons
        categoryBtns.forEach((b) => b.classList.remove("active"))
        // Add active class to clicked button
        btn.classList.add("active")

        // Hide all project containers
        projectContainers.forEach((container) => {
          container.classList.remove("active")
        })

        // Show the selected container
        const category = btn.getAttribute("data-category")
        const target = document.getElementById(`${category}-container`)
        if (!target) return
        target.classList.add("active")

        // reveal any cards in this tab that have not animated in yet
        target.querySelectorAll(".animate").forEach((el) => {
          el.classList.add(el.getAttribute("data-animation"))
          el.classList.remove("animate")
        })
      })
    })

    // Contact form -> Web3Forms, with the sea-breeze notification
    const contactForm = document.getElementById("contact-form")
    const notification = document.getElementById("notification")

    if (!contactForm) return

    const noteIcon = notification && notification.querySelector(".notification-content i")
    const noteText = notification && notification.querySelector(".notification-content p")
    const submitBtn = contactForm.querySelector(".submit-btn")
    const submitLabel = submitBtn ? submitBtn.innerHTML : ""

    function notify(message, ok) {
      if (!notification) { alert(message); return }
      if (noteText) noteText.textContent = message
      if (noteIcon) noteIcon.className = ok ? "fas fa-check-circle" : "fas fa-exclamation-circle"
      notification.classList.add("active")
      setTimeout(() => notification.classList.remove("active"), 4000)
    }

    if (notification) {
      notification.addEventListener("click", () => notification.classList.remove("active"))
    }

    contactForm.addEventListener("submit", (e) => {
      e.preventDefault()

      if (submitBtn) {
        submitBtn.disabled = true
        submitBtn.innerHTML = "Sending..."
      }

      fetch(contactForm.action, {
        method: "POST",
        headers: { Accept: "application/json" },
        body: new FormData(contactForm)
      })
        .then((res) => res.json().then((data) => ({ ok: res.ok, data })))
        .then((result) => {
          if (result.ok && result.data.success) {
            contactForm.reset()
            notify("Message Sent Successfully!", true)
          } else {
            notify(result.data.message || "Something went wrong. Please email me directly.", false)
          }
        })
        .catch(() => notify("Network error. Please email me directly.", false))
        .then(() => {
          if (submitBtn) {
            submitBtn.disabled = false
            submitBtn.innerHTML = submitLabel
          }
        })
    })
  })
